96:         assert(receivableAfter >= receivableBefore);
97: 
98:         uint128 receiveableDelta = receivableAfter - receivableBefore;
99: 
100:         // squeezable before should match receivable now
101:         assert(squeezable == receiveableDelta);
102:     }

